// @ts-nocheck
import { useEffect, useRef } from "react";
import * as THREE from "three";

// ---- Embedded geometry (decimated + procedurally color-painted from the
// uploaded sculpt: white_mesh.glb). Two draw calls: mascot body + chakra disc.
const MESH_DATA = {
  body: {
    positions: "",
    normals: "",
    colors: "",
    indices: "",
    vertexCount: 3019,
    indexCount: 19500,
  },
  disc: {
    positions: "",
    normals: "",
    colors: "",
    indices: "",
    vertexCount: 281,
    indexCount: 2100,
  },
};

function b64ToFloat32(b64, count) {
  const bin = atob(b64);
  const buf = new ArrayBuffer(bin.length);
  const view = new Uint8Array(buf);
  for (let i = 0; i < bin.length; i++) view[i] = bin.charCodeAt(i);
  return new Float32Array(buf, 0, count);
}

function b64ToUint32(b64, count) {
  const bin = atob(b64);
  const buf = new ArrayBuffer(bin.length);
  const view = new Uint8Array(buf);
  for (let i = 0; i < bin.length; i++) view[i] = bin.charCodeAt(i);
  return new Uint32Array(buf, 0, count);
}

function buildGeometry(part) {
  const geo = new THREE.BufferGeometry();
  const positions = b64ToFloat32(part.positions, part.vertexCount * 3);
  const normals = b64ToFloat32(part.normals, part.vertexCount * 3);
  const colors = b64ToFloat32(part.colors, part.vertexCount * 3);
  const indices = b64ToUint32(part.indices, part.indexCount);
  geo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
  geo.setAttribute("normal", new THREE.BufferAttribute(normals, 3));
  geo.setAttribute("color", new THREE.BufferAttribute(colors, 3));
  geo.setIndex(new THREE.BufferAttribute(indices, 1));
  return geo;
}

export default function SudarshanMascotColored3D() {
  const mountRef = useRef(null);

  useEffect(() => {
    const mount = mountRef.current;
    const scene = new THREE.Scene();

    const camera = new THREE.PerspectiveCamera(38, 1, 0.1, 100);
    camera.position.set(0.3, 0.3, 3.4);
    camera.lookAt(0, 0, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mount.appendChild(renderer.domElement);

    scene.add(new THREE.AmbientLight(0x8fa6ff, 0.65));
    const key = new THREE.DirectionalLight(0xffffff, 1.2);
    key.position.set(2, 3, 4);
    scene.add(key);
    const rim = new THREE.PointLight(0x6079e8, 1.4, 8);
    rim.position.set(-3, 1, -1);
    scene.add(rim);

    // group holds body + disc so mouse rotation applies to the whole figure
    const group = new THREE.Group();

    const bodyGeo = buildGeometry(MESH_DATA.body);
    const bodyMat = new THREE.MeshStandardMaterial({
      vertexColors: true,
      roughness: 0.45,
      metalness: 0.25,
    });
    const bodyMesh = new THREE.Mesh(bodyGeo, bodyMat);
    group.add(bodyMesh);

    const discGeo = buildGeometry(MESH_DATA.disc);
    const discMat = new THREE.MeshStandardMaterial({
      vertexColors: true,
      roughness: 0.3,
      metalness: 0.4,
      emissive: new THREE.Color(0xff9819),
      emissiveIntensity: 0.25,
    });
    const discMesh = new THREE.Mesh(discGeo, discMat);
    group.add(discMesh);

    // orbiting glow light to sell the chakra disc as a power source
    const discCenter = new THREE.Vector3();
    discGeo.computeBoundingBox();
    discGeo.boundingBox.getCenter(discCenter);
    const discLight = new THREE.PointLight(0xff9819, 2.2, 3);
    discLight.position.copy(discCenter);
    group.add(discLight);

    // orient + scale: sculpt is Y-up already; sit it centered and a bit lower
    group.scale.setScalar(1.35);
    group.position.set(-0.4, -0.15, 0);
    scene.add(group);

    // faint particle backdrop
    const starGeo = new THREE.BufferGeometry();
    const starCount = 140;
    const starPos = new Float32Array(starCount * 3);
    for (let i = 0; i < starCount; i++) {
      starPos[i * 3] = (Math.random() - 0.5) * 8;
      starPos[i * 3 + 1] = (Math.random() - 0.5) * 6;
      starPos[i * 3 + 2] = (Math.random() - 0.5) * 5 - 2;
    }
    starGeo.setAttribute("position", new THREE.BufferAttribute(starPos, 3));
    const stars = new THREE.Points(
      starGeo,
      new THREE.PointsMaterial({ color: 0x7de8ff, size: 0.02, transparent: true, opacity: 0.45 })
    );
    scene.add(stars);

    const mouse = { x: 0, y: 0 };
    const target = { x: 0, y: 0 };

    function onMove(e) {
      const rect = mount.getBoundingClientRect();
      const x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      const y = ((e.clientY - rect.top) / rect.height) * 2 - 1;
      target.x = THREE.MathUtils.clamp(x, -1, 1);
      target.y = THREE.MathUtils.clamp(y, -1, 1);
    }
    window.addEventListener("mousemove", onMove);

    function resize() {
      const w = mount.clientWidth;
      const h = mount.clientHeight;
      renderer.setSize(w, h);
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
    }
    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(mount);

    const clock = new THREE.Clock();
    let raf;

    function animate() {
      raf = requestAnimationFrame(animate);
      const t = clock.getElapsedTime();

      mouse.x += (target.x - mouse.x) * 0.06;
      mouse.y += (target.y - mouse.y) * 0.06;

      group.rotation.y = 0.4 + mouse.x * 0.55;
      group.rotation.x = -mouse.y * 0.2;
      group.position.y = -0.15 + Math.sin(t * 1.2) * 0.05;

      // spin the disc in place around its own center
      discMesh.position.copy(discCenter);
      discMesh.geometry.computeBoundingBox();
      discMesh.rotation.y = t * 1.4;
      discLight.position.copy(discCenter);

      stars.rotation.y = t * 0.008;

      renderer.render(scene, camera);
    }
    animate();

    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("mousemove", onMove);
      ro.disconnect();
      mount.removeChild(renderer.domElement);
      bodyGeo.dispose();
      discGeo.dispose();
      bodyMat.dispose();
      discMat.dispose();
      renderer.dispose();
    };
  }, []);

  return (
    <div
      style={{
        width: "100%",
        height: "100%",
        minHeight: "560px",
        background: "radial-gradient(ellipse at 50% 40%, rgba(96,121,232,0.18) 0%, #050713 65%)",
        borderRadius: "16px",
        overflow: "hidden",
      }}
    >
      <div ref={mountRef} style={{ width: "100%", height: "100%" }} />
    </div>
  );
}

